head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.v_arrKey = "";
// 화면 리사이징

scwin.fn_GetPar;
scwin.fn_SetPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_Top); // 패널라운드 처리
        window.document.body.scroll = "no";
        const arrPar = new Array();
        /***************************************
        opener에  fn_GetPar의 이름을 가진 함수가 있다면, 이 펑션에 인수를 넘겨 값을 채워 이용한다. 없다면 업종조회후  최초 지정 코드값이 없는 상태
        opener에  fn_SetPar의 이름을 가진 함수가 있다면, 이 펑션에 인수를 넘겨 값을 채워 이용한다. 없다면 선택한 코드값과 코드명칭을 지정하지 않는다.
         ***************************************/
        const parentWin = $c.frame.path("../");
        scwin.fn_GetPar = parentWin.scwin.fn_GetPar;
        if (scwin.fn_GetPar !== undefined) {
            scwin.fn_GetPar(arrPar);
            scwin.v_arrKey = arrPar;
        }
        if (scwin.v_arrKey.length >= 1) {
            await scwin.search();
        } else {
            await $c.win.alert("조회 조건이 없습니다");
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00300_P2.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_SpeclablContn_OnLoadError
 * @description dts_SpeclablContn 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_SpeclablContn_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_SpeclablContn);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00300_P2.dts_SpeclablContn_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_SpeclablContn_OnLoadCompleted
 * @description dts_SpeclablContn 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_SpeclablContn_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts_SpeclablContn.errorMsg) {
            await $c.win.alert(dts_SpeclablContn.errorMsg);
        }

        // 멀티Row의 데이터를 하나로 합치자.
        scwin.appendContents();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00300_P2.dts_SpeclablContn_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name img_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Close_onclick = async function() {
    try {
        // 닫기 버튼 클릭
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00300_P2.img_Close_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description 특기사항 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    // 데이터셋 초기화
    scwin.initDs();

    // 조회조건 필수 체크.
    if (!scwin.chkValid()) {
        return;
    }

    // Lodaing~~~ 표시
    const sbmOptions = {
        id : "sbm_dts_SpeclablContn",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_SpeclablContn=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
// 조회조건이 담길 배열

/**
 * @method
 * @name initDs
 * @description 데이터셋 초기화.
 * @returns {void}
 * @hidden N
 */
scwin.initDs = function() {
    dts_SpeclablContn.removeAll();
};

/**
 * @method
 * @name chkValid
 * @description 조회조건 유효성 체크
 * @returns {void}
 * @hidden N
 */
scwin.chkValid = function() {
    return true;
};

/**
 * @method
 * @name appendContents
 * @description 컨텐츠 append
 * @returns {void}
 * @hidden N
 */
scwin.appendContents = function() {
    let strContent = "<div style='overflow-x:hidden;overflow-y:scroll;width:100%;height:410px;font-family:돋움체;'>";
    for (let nRow = 1; nRow <= dts_SpeclablContn.getRowCount(); nRow++) {
        strContent = strContent + dts_SpeclablContn.getCellData(nRow, "CTNT") + "";
    }
    strContent = strContent + "</div>";
    pan_Ctnt.innerHTML = strContent;

    // 태그 제거후 &nbsp; 만 남는경우 조회된 데이터가 없습니다를 뿌려준다
    // 임시방편으로 만든것 NICE 신용평가에 요청해야 함
    const pattern = /<[^>]+>/g;
    const pan_Ctnt_text = strContent.replace(pattern, '');
    if ($c.stf.trim(pan_Ctnt_text) === "&nbsp;") {
    } else {
    }
};
